The order of event is,

1. Tracer (vpid=1) kill the tracee (vpid=2)
2. Tracer waits for the tracee to die.
3. proot have not yet recieve the death of the tracee yet so the wait call is queued up as a chained syscall.
4. proot got the news that the tracee is dead, send a SIGCHLD to the parent.
5. Before the chained syscall is triggered, the kernel handles the SIGCHLD first, which proot simply forward to the tracer
6. The tracer does a syscall in the signal handler, which proot expected to be the chained syscall.
7. After the syscall finishes, proot restored the register values other than the return value to that of the wait syscall
8. This cause the signal handler to never finish, and also cause the wait call to take the return value of the first syscall in the signal handler.

The order of event (first signal and then the wait syscall) matches the kernel behavior AFAICT so I don't think blocking the signal is the right solution.
Moreover, even though it won't be as reproducible as this case, it's still possible for a process to recieve a signal during other chained syscall as well.

## Expected Behavior
File ownership should be preserved after calls to `setuid` and/or `fork`. Such behavior is often required for some test suites to run properly.

## Actual Behavior
Files created by proot always belong to the current gid:uid.

## Steps to Reproduce the Problem

I wrote a simple program in C to show the issue.

``` c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

void writeFile(const char* filename)
{
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "fopen failed\n");
        exit(1);
    }
    fputs("This is a file\n", file);
    fclose(file);
}

void printOwner(const char* file, bool parent)
{
    struct stat stat;

    if (lstat(file, &stat) < 0) {
        fprintf(stderr, "lstat failed\n");
        exit(1);
    }

    printf("%s sees '%s' with owner %d:%d\n", parent ? "Parent" : "Child", file, stat.st_gid, stat.st_uid);
}

void testFork(bool parentIsUser, bool childIsUser)
{
    const char* const parentFilename = "file created by parent";
    const char* const childFilenameBeforeSetuid = "file created by child before setuid";
    const char* const childFilename = "file created by child";

    pid_t pid;

    if (parentIsUser) {
        setgid(1000);
        setuid(1000);
    }

    writeFile(parentFilename);
    printOwner(parentFilename, true);

    pid = fork();
    if (pid == 0) {
        if (childIsUser) {
            writeFile(childFilenameBeforeSetuid);
            printOwner(childFilenameBeforeSetuid, false);

            setgid(1000);
            setuid(1000);

            printOwner(childFilenameBeforeSetuid, false);
        }

        printOwner(parentFilename, false);

        writeFile(childFilename);
        printOwner(childFilename, false);

        exit(0);
    } else {
        waitpid(pid, NULL, 0);
    }

    if (childIsUser) {
        printOwner(childFilenameBeforeSetuid, true);
        unlink(childFilenameBeforeSetuid);
    }
    printOwner(childFilename, true);
    unlink(parentFilename);
    unlink(childFilename);
}

void test(bool parentIsUser, bool childIsUser)
{
    struct stat stat;
    pid_t pid;

    pid = fork();
    if (pid == 0) {
        testFork(parentIsUser, childIsUser);
        exit(0);
    } else {
        waitpid(pid, NULL, 0);
    }
}

int main()
{
    puts("--------\nParent is root, child is root\n--------");
    test(false, false);
    puts("--------\nParent is root, child is user\n--------");
    test(false, true);
    puts("--------\nParent is user, child is user\n--------");
    test(true, true);
    puts("--------");
}
